INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "ランドソルを囲む壁に絵を？\nふぅん、楽しそうね。\nここに描けばいいのかしら？", 106431, 0.5, 1, 112029, 0, 10, 11, 112);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", 112029, "", "", 112030, "", "", 91, 112);
