INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "え？　ランドソルの壁を……\nぐるっと一周？", 106431, 0.5, 1, 112039, 0, 10, 11, 112);
