INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "じゃんじゃじゃ～ん！\n自分、心を込めて描いたッス！\n最初は不安もあったッスけど、\nそんなのは邪魔なだけッスよね！", 100511, 0.5, 1, 2112009, 0, 10, 11, 2112);
