INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "一筆入魂で\n正義の心を込める方が大切ッス。\nこれで街の悪い人たちも\n正義に目覚めてくれるといいッスね！", 100511, 0.5, 1, 2112012, 0, 10, 11, 2112);
