INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "これも立派な下克上への道。\nバレない所から少しずつ……って！\nあそこに居るのはボス！？\nこうしちゃいられない！　逃げるです！", 106611, 0.5, 1, 4012012, 0, 10, 11, 4012);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", 0, "", "", 4012013, "", "", 91, 4012);
