INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "牧場の仕事で柵を塗ったりすっけど、\n絵を描くってのはなかなかねぇから\n苦労したべ。", 103311, 0.5, 1, 4112009, 0, 10, 11, 4112);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", 0, "", "", 4112010, "", "", 91, 4112);
