INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "その割にはよく描けたと思うけんど……\nどうだべ？　牧場に来てくれる人たちが\nこの絵を見てほっこりしてくれると\nうれしいなぁ。", 103311, 0.5, 1, 4112012, 0, 10, 11, 4112);
