INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "平気だよ～！\nユイちゃんもレイさんもすっごく\n上手だもん！　ま、まああたしも\nちょっと照れくさいけど。えへへ。", 100111, 0.5, 1, 5012023, 0, 10, 11, 5012);
