INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "上手に出来たかな？\n練習の成果が出てるといいけど……\nあの、私の絵、どうですか？", 103611, 0.5, 1, 6712009, 0, 10, 11, 6712);
