INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "ふふ。壮観じゃ。世界征服が進んでいる\nようで心が踊るのう……\nそうじゃ！　このまま我らの絵で\n壁を埋め尽くすのはどうじゃ？", 104411, 0.5, 1, 8012026, 0, 10, 11, 8012);
