INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "それならミヤコはプリンを描くの！\nプリンをい～っぱい描いて、\nプリンで街を征服してやるの！", 100711, 0.5, 1, 8012036, 0, 10, 11, 8012);
