INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "征服とかはわからないけど……\nそれなら私は、好きなゲームの絵とか\nたくさん描いてみたい、かも……！", 102211, 0.5, 1, 8012041, 0, 10, 11, 8012);
