INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "そんなことないよ、アヤネちゃん……！\nすっごく元気が出てくるような絵で\n私は、大好きだよ……♪", 102111, 0.5, 1, 8512027, 0, 10, 11, 8512);
