INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "そうね。\nのびのびとした描き方で、\n見ていて気持ちいいわ。\nとってもアヤネらしいわね。", 102811, 0.5, 1, 8512032, 0, 10, 11, 8512);
