INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "みんなよく描けてます……！\n私のドジで台無しにしちゃいそうで\n不安になってきました……っ！", 102511, 0.5, 1, 8512037, 0, 10, 11, 8512);
