INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "ふふ、こうしてみなさまと一緒に\n絵を描くというのもまた\n楽しいものでございますね。", 105911, 0.5, 1, 8612022, 0, 10, 11, 8612);
