INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "そうね。慣れないせいもあって\n緊張しちゃうけど、\nコッコロさんやみんなが一緒だと\n落ち着いて、楽しくやれる気がするわ。", 106411, 0.5, 1, 8612027, 0, 10, 11, 8612);
