INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "一人よりみんなの方が、\n落ち着いて楽しく過ごせる……か。\nあたしたちが囲む食卓と\n一緒ってことかしらね。", 106011, 0.5, 1, 8612032, 0, 10, 11, 8612);
