INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "う～ん……最近少し絵柄が\n変わってきた気がするわね？\nなんだか【美食殿】のみんなに\n影響されてるような……？", 106011, 0.5, 1, 8812009, 0, 10, 11, 8812);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", 0, "", "", 8812010, "", "", 91, 8812);
