INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "……まあ、あんまり悪い気はしないけど。\n色んな絵が描けるってことだもん。\nたまにはあいつらに\n感謝しなくちゃね。", 106011, 0.5, 1, 8812012, 0, 10, 11, 8812);
