INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "ふぅ、出来たわね。\nついつい夢中になっちゃったわ。\n子どもたちが一生懸命描く姿に\n影響されちゃったみたいね。", 102811, 0.5, 1, 9312009, 0, 10, 11, 9312);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", 0, "", "", 9312010, "", "", 91, 9312);
