INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "ふふっ、こうやって大人も子どもも\n関係なく、みんなでひとつの仕事を\n成し遂げるっていうのも、\nなかなか気持ちいいものね。", 102811, 0.5, 1, 9312012, 0, 10, 11, 9312);
