INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "できました……！\nえへへ、いままでの絵の中で\n一番よく描けた気がします……♪\n自信作、なんておおげさかな……？", 102111, 0.5, 1, 11512022, 0, 10, 11, 11512);
