INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "すごいすご～い！\nクルミ、とっても上手！\nぷうきちも『すげえな！』って\nほめてるよ！", 102311, 0.5, 1, 11512027, 0, 10, 11, 11512);
