INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0, "", "vo_wac_220705_004", "vo_wac_220705", "", "", 14112044, "", 0, 21, 14112);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "はは、そりゃ助かった。\nお前さん、物言いは突飛だが、\nそういうところにはよく気が回るねえ。\nいい子じゃないか。", 105611, 0.5, 1, 14112045, 0, 10, 11, 14112);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", 0, "", "", 14112046, "", "", 91, 14112);
