INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0, "", "vo_wac_220705_005", "vo_wac_220705", "", "", 14112049, "", 0, 21, 14112);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "なっ、いい子とか言うなぁ！\nて、手がすいたからやっただけで、\nそこはせめて全知全能と……\nうぅ、生暖かい目で見るなぁっ！", 100911, 0.5, 1, 14112050, 0, 10, 11, 14112);
