INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0, "", "vo_wac_220707_000", "vo_wac_220707", "", "", 14312021, "", 0, 21, 14312);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "ふふ、絵を描くのって楽しいさ～！\n描いても描いても飽きないし……\n歌って踊ればもっと楽しくなるさ～！", 101711, 0.5, 1, 14312022, 0, 10, 11, 14312);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", 0, "", "", 14312023, "", "", 91, 14312);
