INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "バ、バカ！　絵筆持ったまま\n踊るなって！　尻尾に\n絵の具がつくと落とすの大変なんだよ！", 104311, 0.5, 1, 14312027, 0, 10, 11, 14312);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", 0, "", "", 14312028, "", "", 91, 14312);
