INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "うちもこの間、それやってしもうたなぁ。\nふふ、でも安心しておくれやす。\nきれいに落とす方法、\nうちが教えてあげますえ。", 101011, 0.5, 1, 14312032, 0, 10, 11, 14312);
