INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "ふふ、帰ったらみんなで\nお風呂に入らないといけないね。\n……私も少し服を汚してしまった。\n自分がキャンバスになった気分だよ。", 101411, 0.5, 1, 14312037, 0, 10, 11, 14312);
