INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "はは、アタシの筆さばきだって\nなかなか様になってたろう？\n……それで？　お前さんは\n誰の絵が一番だと思うんだい？", 105611, 0.5, 1, 14712046, 0, 10, 11, 14712);
