INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "うん、これで完璧……おっと。\nもうこんな時間か。\nいやはや絵を描くというのは、\n突き詰めだすとキリがないね。", 101411, 0.5, 1, 15812009, 0, 10, 11, 15812);
