INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "よし、今度も素晴らしい完成度だ！\n役割分担をしたら、飛躍的に\n描くのが早くなったな！", 105311, 0.5, 1, 16412025, 0, 10, 11, 16412);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", 0, "", "", 16412026, "", "", 91, 16412);
