INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0, "", "vo_wac_220728_001", "vo_wac_220728", "", "", 16412029, "", 0, 21, 16412);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "シュバッ！　シュバババッ！\n色塗りはワタシにお任せデース！\nこの絵筆二刀流で、瞬く間に\nカラフルにしてみせマース！", 103011, 0.5, 1, 16412030, 0, 10, 11, 16412);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", 0, "", "", 16412031, "", "", 91, 16412);
