INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0, "", "vo_wac_220728_002", "vo_wac_220728", "", "", 16412034, "", 0, 21, 16412);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "絵の下書きはボクに任せて。\nすべての美しさの源になる存在……\nそれがボクだからね！", 100811, 0.5, 1, 16412035, 0, 10, 11, 16412);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", 0, "", "", 16412036, "", "", 91, 16412);
