INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "あっ、道具のお片づけは\n私がしておきました……\nこういう地味な作業でも、\nお役に立ててるといいんですけど……", 105511, 0.5, 1, 16412045, 0, 10, 11, 16412);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", 0, "", "", 16412046, "", "", 91, 16412);
