INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "うむ！　完璧なコンビネーションだ！\n過去一番の団結と言っても過言ではないな！\n……それはそれでちょっと複雑だが。\nこの調子でお絵描き事業を完遂するぞ！", 105311, 0.5, 1, 16412050, 0, 10, 11, 16412);
