INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "ふぇっ、私の絵の評判がいい！？\n後ろで見てた人に褒められてた？\nそ、そんな、私の絵なんて……\nもちろん真面目に描きましたけど……", 105511, 0.5, 1, 16712013, 0, 10, 11, 16712);
