INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "うん、これでいいかな？\n鎧をつけたまま絵を描くのも、\nやっと慣れてきた感じだね。", 104711, 0.5, 1, 16812009, 0, 10, 11, 16812);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", 0, "", "", 16812010, "", "", 91, 16812);
