INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "ううむ、指定通りに描いてはみたが、\nいかんせん芸術性に欠けるな……\nぼくの個性は不要とのことだが、\n端的に言って弾圧じゃあないか。", 111011, 0.5, 1, 17312009, 0, 10, 11, 17312);
