INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "だが翻せばこれは、ぼくの芸術が\n人心を揺るがすと懼れられた証左だ。\nすなわち、ぼくは否定されることで\nかえって肯定されたのだよ。ふはは。", 111011, 0.5, 1, 17312013, 0, 10, 11, 17312);
