INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "よーし、ざっとこんなもんだろ！\nこういうのはあたし向きじゃないと\n思ってたんだが、慣れてくると\n案外楽しいもんだな♪", 104311, 0.5, 1, 17612022, 0, 10, 11, 17612);
