INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "芸術という名の頭脳労働でありながら、\n程よく体を動かせて運動にもなるしね。\n名探偵の余暇の活動としても、\n最適解だと思うよ♪", 101411, 0.5, 1, 17612027, 0, 10, 11, 17612);
