INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "一応、これってギルドの\nお仕事なんやけどなぁ……\nまぁ、なんでも楽しゅうできるのが、\n一番ええことやからねぇ♪", 101011, 0.5, 1, 17612032, 0, 10, 11, 17612);
