INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "そうだねー♪\n遊びでもお仕事でも、\nみんなで元気に頑張れば、\nなんくるないさー♪", 101711, 0.5, 1, 17612037, 0, 10, 11, 17612);
