INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "さらにここに、我らの生きた証として、\n前世からの宿命を感じさせる刻印を……\nえっ、公共の壁だからそれはダメ？\nそうか……残念だ……", 100911, 0.5, 1, 18712012, 0, 10, 11, 18712);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", 0, "", "", 18712013, "", "", 91, 18712);
