INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "この調子でどんどん絵を練習して、\n弟くんへの愛情を表現していかないと。\nまずは弟くんに膝枕してるお姉ちゃんの\n絵で、ランドソルを包囲しようかな♪", 104911, 0.5, 1, 19112012, 0, 10, 11, 19112);
