INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "よし、できあがりだ！\n畑違いな依頼の気もするが、\n軍人たるもの、どんな任務でも\n忠実にこなさなければな。", 105311, 0.5, 1, 19712009, 0, 10, 11, 19712);
