INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("wac_talk_smile_loop", "", "wac_talk_smile_in", 100811, "", 1, 19812037, 0.2, 0, 3, 19812);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0, "", "vo_wac_220831_002", "vo_wac_220831", "", "", 19812038, "", 0, 21, 19812);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "美を伝えるという点では同じだよ。\nボクだって歯磨きをするボクや\nお昼ご飯を食べるボクがいるけど、\n全て美しいボクには違いないでしょ？", 100811, 0.5, 1, 19812039, 0, 10, 11, 19812);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", 0, "", "", 19812040, "", "", 91, 19812);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "wac_idle_smile", 100811, "", 1, 19812041, 0.2, 1, 3, 19812);
