INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "それは流石に違う気がします……\nでも、みんなで描いた絵が、\n浮世絵みたいにきれいに\nできたのはそのとおりですね♪", 105511, 0.5, 1, 19812049, 0, 10, 11, 19812);
