INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "ふぃ～、やっと終わったです。\n絵を描くのは嫌いじゃねーですけど、\nボスはなんでもかんでもあたしらに\n仕事を押しつけすぎでは……", 106611, 0.5, 1, 20712009, 0, 10, 11, 20712);
