INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "あたしが下剋上した暁には、\n雑巾がけから夕飯の買い物まで、\nぜ～んぶボスに押しつけてやるです！\nいつになるかは分からねーですけど！", 106611, 0.5, 1, 20712013, 0, 10, 11, 20712);
