INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "うん、よくできたかな？\nこうして絵を描いていると\n気分が落ち着くな～\nやっぱり、好きなことだから。", 106711, 0.5, 1, 20912009, 0, 10, 11, 20912);
