INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "君はどうかな？　絵は好き？\n好きだったら嬉しいかな～？\n興味のある人と同じ趣味だったら、\n素敵だなって思うでしょ♪", 106711, 0.5, 1, 20912012, 0, 10, 11, 20912);
