INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "なんか自動描画プログラム？\nとかいうのが調整ダルくて\n諦めたッつってたけど。\n何させるつもりだったんだ、あの人……", 110811, 0.5, 1, 21212012, 0, 10, 11, 21212);
