INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0, "", "vo_wac_220915_000", "vo_wac_220915", "", "", 21312017, "", 0, 21, 21312);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "あのう、チエルまだバイト代、\n通称国家予算もらってないんですけど。\nコレ大丈夫なやつですかね。\n国家バックレ案件じゃないですよね？", 110911, 0.5, 1, 21312018, 0, 10, 11, 21312);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", 0, "", "", 21312019, "", "", 91, 21312);
