INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "まあまあ、落ちつけ後輩たち。\n慌てる理系は貰いが少ないと言うぞ。\n国家予算ともなれば、相応に煩雑な\n手続きがあるのだろう。座して待て。", 111011, 0.5, 1, 21312028, 0, 10, 11, 21312);
