INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "おわりました～……\nやっぱり、絵を描くのはいいですね。\nぼっちが一人で絵を描いてても、\nそんなに違和感ないですから。", 104011, 0.5, 1, 21412009, 0, 10, 11, 21412);
