INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "はっ、そうです！\nこの調子で、ぼっちでも関係ない\n趣味を発掘しまくれば、ぼっちライフも\n充実していくのでは……！？", 104011, 0.5, 1, 21412012, 0, 10, 11, 21412);
