INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "ふぅ、これでできあがりね。\nみんなもすごく上手に描けてるし、\nよく頑張ったわね♪", 102811, 0.5, 1, 23212022, 0, 10, 11, 23212);
