INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "えへへ～、楽勝だよ♪\nもう何回か描いてるし、\n救護院でもクルミたちと\n練習してるからねー", 102311, 0.5, 1, 23212027, 0, 10, 11, 23212);
