INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "よし、任務完了だ！\n……と、威勢よく言ってみたはいいが、\n絵を描いてばかりで、いざという時に\n本分が果たせるのだろうか……", 105311, 0.5, 1, 23512009, 0, 10, 11, 23512);
