INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "このままでは軍人としての\n勘も鈍ってしまう！　今すぐ帰って、\nギルドの仲間たちと訓練の続きだ！", 105311, 0.5, 1, 23512012, 0, 10, 11, 23512);
