INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "うーん……なんと言いますか。\n絵を描くのは楽しいんですけど、\nちょっと刺激が足りないというか……", 104511, 0.5, 1, 23612009, 0, 10, 11, 23612);
