INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "絶対に違うと思います……\n二人とも、自分の好きなものに\n忠実なだけというか……", 105511, 0.5, 1, 23812041, 0, 10, 11, 23812);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", 0, "", "", 23812042, "", "", 91, 23812);
