INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "ほら、いつまでも壁の前で\nダラダラしてないで帰るぞ！\n私たちに必要なのは、尊さだの\n芸術だのではなく、訓練なんだからな！", 105311, 0.5, 1, 23812046, 0, 10, 11, 23812);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", 0, "", "", 23812047, "", "", 91, 23812);
