INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "団長といい、トモちゃんといい、何を\n寝言のようなことぬかしているんだ？\nワタシは職務熱心だからな、平時でも\n喜んで剣を振るっているぞ♪", 107111, 0.5, 1, 25312032, 0, 10, 11, 25312);
