INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "ホントにランドソルって広いッスよね～\nみんなで壁に絵を描いてるはずなのに、\nまだまだ終わりが見えないッス。", 100511, 0.5, 1, 25512009, 0, 10, 11, 25512);
