INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "また一つ、かわいいボクに\nよって美しい芸術が完成\nしてしまったよ……天はボクに、\nいくつ才能を与えるつもりなのかな？", 100811, 0.5, 1, 25712009, 0, 10, 11, 25712);
