INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "ふぅ……これで完成、です。\n前よりも上手に描けたでしょうか？\nやっぱり絵を描くのって楽しいですね。", 103811, 0.5, 1, 26212022, 0, 10, 11, 26212);
