INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "実は、ちょっとだけ\nフラフラ～ってしてます……\nみんなでお絵描きするのが楽しくて、\nはしゃぎすぎちゃったみたいで……", 103811, 0.5, 1, 26212032, 0, 10, 11, 26212);
