INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "あ、だったら、リマの背中を借りたら？\n今日は天気もいいし、いい感じに\nふわふわで最高だったよ～", 102611, 0.5, 1, 26212037, 0, 10, 11, 26212);
