INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "よし、描けた。\nみんなで話し合ったりして、\nちょっと時間はかかったけど、\n悪くない出来じゃないかな？", 101411, 0.5, 1, 26222022, 0, 10, 11, 26222);
