INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "せやねぇ♪\nみんなでわいわいしながら、\nまったりと描くんも楽しかったわぁ♪\n絵にもそれが表れてます♪", 101011, 0.5, 1, 26222027, 0, 10, 11, 26222);
