INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "でーじ分かるさ～！\n見てるとこう、ワクワクしてきて\n思わず踊りたくなるね～\nよ～し、マコトも一緒に踊るさ～♪", 101711, 0.5, 1, 26222032, 0, 10, 11, 26222);
