INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "え、あたしも踊るのかよっ！？\nていうか、さっきも踊ってただろっ？\nあ、あんまり引っ張るなって！", 104311, 0.5, 1, 26222037, 0, 10, 11, 26222);
