INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "やっぱり踊って歌いながら絵を描くのは\nでーじ楽しいさ～♪\nもっと踊って……え？\n絵の具がはねちゃってる～？", 101711, 0.5, 1, 26612009, 0, 10, 11, 26612);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", 0, "", "", 26612010, "", "", 91, 26612);
