INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "集中してて気付かなかったさ～！\nでもこれくらいなんくるないさ～ね～♪\nそれより、良かったらキミも、\n私と一緒に踊るさ～♪", 101711, 0.5, 1, 26612012, 0, 10, 11, 26612);
