INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "うーん、上達してきた気もするけど、\nまだまだって感じだなぁ……\n他のやつはどんな絵を描いてるんだ？\nどれどれ、ちょっと見せてもらうか。", 104311, 0.5, 1, 26712009, 0, 10, 11, 26712);
