INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "やっぱりみんなうまいな。\nおっ？　これなんて、すげぇかわい……\nいやいや、うん、すげぇいい絵だぜ。\nあ、あたしも負けてらんねぇな！", 104311, 0.5, 1, 26712013, 0, 10, 11, 26712);
