INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "まぁ、ミフユさんったら。\n私たちが手掛けているのはアート\nなんですから、もっと自由に、\n己の感性に従って描くべきですわ！", 103211, 0.5, 1, 27012027, 0, 10, 11, 27012);
