INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "やはりこの姿だと、作業しやすいのう！\nふふっ、これもお主のおかげじゃな。\nどれ、少しなら褒美をやっても良いぞ？\nなに……絵を見れるだけで十分じゃと？", 104411, 0.5, 1, 27312009, 0, 10, 11, 27312);
