INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "これは帰ったら早速試して……\nえ？　そのままでいいって？\n確かにその通りだね！\nさすがキミ、ボクの美を理解してるよ♪", 100811, 0.5, 1, 27612012, 0, 10, 11, 27612);
