INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0, "", "vo_wac_221119_003", "vo_wac_221119", "", "", 27812040, "", 0, 21, 27812);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "うむ……もはや、何も言うまい。\nしかし共同作戦というのは悪くないな。\nこれはチームプレイの\n良い訓練になるぞ！", 105311, 0.5, 1, 27812041, 0, 10, 11, 27812);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", 0, "", "", 27812042, "", "", 91, 27812);
