INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "ふふっ、ボクが一番\n輝いちゃって申し訳ないけどね♪\n流れる汗も太陽に照らされて、\nボクを彩ってるみたいじゃないか♪", 100811, 0.5, 1, 27812046, 0, 10, 11, 27812);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", 0, "", "", 27812047, "", "", 91, 27812);
