INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "絵を描くだけで、こ、こんなに\n興奮できるなんて思いませんでした……\nきっとこの後もドＳさんから絵について\nあることないこと聞かれて……ぐふふ♪", 104511, 0.5, 1, 27812051, 0, 10, 11, 27812);
