INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "今日はここまでっと。\nちゃんと道具の手入れもしたから、\n絵の具のノリが良かったかな。\nいい線が描けた気がするよ♪", 103711, 0.5, 1, 28212009, 0, 10, 11, 28212);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", 0, "", "", 28212010, "", "", 91, 28212);
