INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "さてと、それじゃあ他の絵を眺めながら\n見回りをしてこよう。\nこんな平和な日々を守る為に\n仕事も頑張らないと♪", 103711, 0.5, 1, 28212012, 0, 10, 11, 28212);
