INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "うん、依頼された部分は描けたかな。\nランドソルを守るだけではなく、\nこういう任務も大事だよね。\n上手に描けているといいんだけど。", 104711, 0.5, 1, 28312009, 0, 10, 11, 28312);
