INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "ジュンさん、それにみんなも、\n手伝ってくれてありがとうッス！\nおかげで、ワイルドなかっこいい絵に\n仕上がったッスよ♪", 100511, 0.5, 1, 28412042, 0, 10, 11, 28412);
