INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "ふんっ！　くだらんな！\n血湧き肉躍る命の駆け引きのように\n荒々しく筆を振るう！　それこそ芸術！\n坊やもそう思うだろう？", 107111, 0.5, 1, 28512012, 0, 10, 11, 28512);
