INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "あ、今度お姉ちゃんに送る手紙に\n絵を描いてみようかな？\n喜んでくれたらうれしいな。", 103811, 0.5, 1, 28612012, 0, 10, 11, 28612);
