INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0, "", "vo_wac_221201_001", "vo_wac_221201", "", "", 29012022, "", 0, 21, 29012);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "ふふ……\nアンはなんでも楽しそうにやるけどね。\n一緒にいる私まで楽しくなるよ……", 109411, 0.5, 1, 29012023, 0, 10, 11, 29012);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", 0, "", "", 29012024, "", "", 91, 29012);
