INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "ルゥもです！\nちょっとはみ出しちゃっても、\nアンせんぱいは、ぜーんぶいいね！って\n笑ってくれるです！", 109311, 0.5, 1, 29012028, 0, 10, 11, 29012);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", 0, "", "", 29012029, "", "", 91, 29012);
