INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "えへへ～なんだか照れちゃうな～！\nでも、そうだよね。みんなと一緒に\n一つのことをやるってすっごく楽しい！\nこの楽しさは魔法じゃ叶えられないよ！", 109211, 0.5, 1, 29012033, 0, 10, 11, 29012);
