INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "最近、もうすっかりお絵描きに\nハマっちゃいました～♪\n筆とか絵の具とかも自分で買って、\nおうちでもお絵描きしてるんですよ？", 100611, 0.5, 1, 30912009, 0, 10, 11, 30912);
