INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "うん！\n……でも、このあたりって\n誰が色塗り担当だったっけ？\n気づいたら塗り終わってたよね？", 100611, 0.5, 1, 31112031, 0, 10, 11, 31112);
