INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "毎度思うんだけどさ～\nこう、一気にちゃちゃっと\n壁に絵を自動で描いてくれる\n魔法とかないの？", 102611, 0.5, 1, 32112022, 0, 10, 11, 32112);
