INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "【牧場（エリザベスパーク）】には、\nそんな高度な魔法を扱える人が\nいないので……お姉ちゃんなら\nできるかもしれないですけど。", 103811, 0.5, 1, 32112027, 0, 10, 11, 32112);
