INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "っていうか、大人っぽさってなに？\n麦しゅわが飲めるとか、そういうの？\nよくわかんないよ～！\nちゃんイオはわかる？", 101611, 0.5, 1, 32312023, 0, 10, 11, 32312);
