INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "う～ん、そうね～……\nその質問に答えがないって\n実感できた時が、きっと二人が\n大人になったときだと思うわ♪", 101811, 0.5, 1, 32312028, 0, 10, 11, 32312);
