INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "色もカラフルで、なんだか\nアイスキャンディーみたいでしょう？\n……えっ、食べたいの？　\nさすがにお腹壊しちゃうと思うけど……", 106411, 0.5, 1, 32412012, 0, 10, 11, 32412);
