INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "じゃあ、新しくできた\nケーキ屋さんに行ってみない？\nショートケーキと苺のタルトが\nすごくおいしそうだったんだよね～♪", 100111, 0.5, 1, 33212023, 0, 10, 11, 33212);
