INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "大勢で絵を描く、という試みは\n素晴らしいものなのですが、参加者に\n女性が多いのは困りものですね。\n主に、父が原因なのですが。", 103111, 0.5, 1, 33612009, 0, 10, 11, 33612);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", 0, "", "", 33612010, "", "", 91, 33612);
