INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "もう何度父がナンパした他のギルドの\n方々に頭を下げたか分かりません……\n次にやったらペンキ缶に沈めると\n伝えてからは、大人しくなりましたが。", 103111, 0.5, 1, 33612012, 0, 10, 11, 33612);
