INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "……この仕事って、気を付けないと\n服が塗料で汚れちゃうのが困るわね。\n昨日はアカリが思いっきり汚してきて、\nお説教する羽目になったし。", 102211, 0.5, 1, 33812009, 0, 10, 11, 33812);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", 0, "", "", 33812010, "", "", 91, 33812);
