INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "そう、お説教したばっかりなのよ……\nなのに、今日に限って私もスカートに\n思いっきりペンキが跳ねるなんて！\nあの子になんて言い訳するのよ～！？", 102211, 0.5, 1, 33812012, 0, 10, 11, 33812);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", 0, "", "", 33812013, "", "", 91, 33812);
