INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "こういう、でっけぇ絵を眺めてると、\n心が洗われるような気分になるべな～\nなんだか、爽やかな傑作ギャグを\n思いつけそうな気がしてきたべ！", 103311, 0.5, 1, 34112009, 0, 10, 11, 34112);
