INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "ちょっと待ってろ～、う～ん……うん！\nみんなで描いた絵は、\nやっぱり「絵」えな～！\n……今のは取り消しだべ。", 103311, 0.5, 1, 34112012, 0, 10, 11, 34112);
