INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "似たようなもので満足\nしてくれないかなぁ？\n茶碗蒸しとか♪", 100611, 0.5, 1, 34312036, 0, 10, 11, 34312);
