INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "嫌いだったら、あんな楽しそうに\n構いに行ったりしないからね。\nもう少し眺めていたいけれど……\nそろそろ、助け舟を出してあげようか。", 104711, 0.5, 1, 35812037, 0, 10, 11, 35812);
