INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "色には見た人の気分を\n変化させる効果があるというけど……\n確かに色鮮やかな壁を見ていると、\n楽しい気分になってくるね。", 104711, 0.5, 1, 35912009, 0, 10, 11, 35912);
