INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "私の鎧も、このようにカラフルで\nかわいげのある塗装を試してみようか。\n団員たちの士気もあがるかもしれない。\n……やめた方がいい？　そうかな？", 104711, 0.5, 1, 35912012, 0, 10, 11, 35912);
