INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "……自分のことが好きだから、\nそれだけ熱心に教えてくれてるって？\nウソッス！　絶対の絶対、自分の\nリアクションを楽しんでるだけッス～！", 100511, 0.5, 1, 36112012, 0, 10, 11, 36112);
