INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "もちろん、この絵だけじゃないよ？\nこれからは一緒に、いろいろ\n楽しいことに挑戦していこ～♪", 100111, 0.5, 1, 36912032, 0, 10, 11, 36912);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", 0, "", "", 36912033, "", "", 91, 36912);
