INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "そうだね♪\n幸せ過ぎて、絶対に忘れたくない……\nもし忘れても、必ず思い出したい……\nそんな思い出を、作っていきたいな。", 100211, 0.5, 1, 36912037, 0, 10, 11, 36912);
