INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "ハ？　先輩、いまなんて言いました？\nこの城壁お絵かきプロジェクトに、\nカルミナちゃんたちも参加してる？\n三人ともうっかり壁にサイン書いてた？", 110911, 0.5, 1, 37712009, 0, 10, 11, 37712);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", 0, "", "", 37712010, "", "", 91, 37712);
