INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "あのさあ……カルミナ創作小話は\nチエルもよく匿名で投稿しますけども、\n現実に反したお馬鹿キャラみたいな\n解釈広めるのはやめましょうよ。ね？", 110911, 0.5, 1, 37712012, 0, 10, 11, 37712);
