INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "「ドッキリ大成功です！」つってね。\nプラカードと国家予算持ってね。\nあるある、絶対ソレだわ。", 110811, 0.5, 1, 37912031, 0, 10, 11, 37912);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", 0, "", "", 37912032, "", "", 91, 37912);
