INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "あーウケる。\nしたらカリンさん出てくるまで、\nしばらくこのまま待っとこ。ね。", 110811, 0.5, 1, 37912034, 0, 10, 11, 37912);
