INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "今回も上手にできたにゃ～♪\nあたしたちも気づけばすっかり\n絵描きの風格になったにゃ。\nこれで新しい商売でも始めるにゃ？", 104611, 0.5, 1, 38012022, 0, 10, 11, 38012);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", 0, "", "", 38012023, "", "", 91, 38012);
