INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "麦しゅわ！　麦しゅわの絵を描くの！\nそれをね～、酒場とかに売って～……\nそのお金で、麦しゅわを買うの～♪\n……ひっく。", 103411, 0.5, 1, 38012032, 0, 10, 11, 38012);
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", 0, "", "", 38012033, "", "", 91, 38012);
