INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "業務終了と同時に麦しゅわをあおることの\n是非はさておき、それは名案ですわ！\n今回のノウハウを活かして、商店向けの\n看板制作にチャレンジいたしましょう！", 103211, 0.5, 1, 38012037, 0, 10, 11, 38012);
