INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "いっちょあがりだべさ～♪\nしかし、壁ももうほとんど埋まって、\nあんま描くとこが残ってねぇな？", 103311, 0.5, 1, 38212022, 0, 10, 11, 38212);
