INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "みんなで、がんばって\n描き続けてきましたから……\n最後まで、丁寧にお仕事を\nしたいですね♪", 103811, 0.5, 1, 38212027, 0, 10, 11, 38212);
