INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "この作業も長くやってきたってのに、\n結局考えてることはバラバラだねぇ……\nそれでも上手いこと回っていくのが、\nウチのギルドのよさなんだけどさ。", 105611, 0.5, 1, 38612046, 0, 10, 11, 38612);
