INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "いよいよ、この仕事も\n終わりが近づいてきたんじゃない？\n大きな壁だったけれど、みんなで\n協力したら、あっという間だったわね。", 105111, 0.5, 1, 40412009, 0, 10, 11, 40412);
