INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "……というわけで！\nカリンさん、お待たせしました。\nランドソルの景観向上事業、\n全力全開でやり遂げましたよ☆", 105811, 0.5, 1, 40922004, 0, 10, 11, 40922);
