INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (1, 0, "みなさん、本当にお疲れさまでした！\nこれだけ大きな壁に絵を描くのは\n大変だったと思いますが、\nとても鮮やかな景観になりましたよ♪", 118511, 0.5, 1, 40922009, 0, 10, 11, 40922);
